1	import Link from "next/link";
2	import { requireUser } from "@/lib/auth";
3	import { EmptyState } from "@/components/ui/primitives";
4	import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
5	import {
6	  listFolders,
7	  listMessages,
8	  getMailboxes,
9	} from "@/lib/actions-mail";
10	import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
11	import { mailAccessState, type MailAccessState } from "@/lib/mail/imap";
12	import { MailClient } from "@/components/customer/mail/MailClient";
13	
14	export const dynamic = "force-dynamic";
15	
16	export const metadata = { title: "Mail — Nxeon" };
17	
18	export default async function MailPage({
19	  searchParams,
20	}: {
21	  searchParams: Promise<{ mailbox?: string }>;
22	}) {
23	  const user = await requireUser();
24	  const { mailbox: requested } = await searchParams;
25	
26	  let folders: MailFolder[] = [];
27	  let mailboxes: MailboxInfo[] = [];
28	  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
29	  let inboxPath = "INBOX";
30	  let signature = "";
31	  let active: string | undefined;
32	  let failed = false;
33	
34	  const wanted = requested?.trim().toLowerCase();
35	
36	  try {
37	    if (wanted) {
38	      // Honour `?mailbox=` (the per-mailbox "Open inbox" link on the Business
39	      // Email page) but ONLY when the address is one this user actually owns.
40	      // `getMailboxes` is already scoped to their own subscriptions, so an
41	      // address outside that list is dropped rather than passed to
42	      // `resolveMailbox` — a bad or hostile value lands on the default mailbox
43	      // instead of turning the whole page into an error state. The mailbox list
44	      // has to be resolved first here, hence the extra round trip.
45	      mailboxes = await getMailboxes();
46	      if (mailboxes.length === 0) throw new Error("no mailbox");
47	      if (mailboxes.some((m) => m.address.toLowerCase() === wanted)) active = wanted;
48	      folders = await listFolders(active);
49	    } else {
50	      // No deep link: `resolveMailbox(undefined)` and `getMailboxes` both order by
51	      // createdAt asc, so they agree on which mailbox is the default and the two
52	      // IMAP round trips can overlap — this is the common load and it stays fast.
53	      const [f, mb] = await Promise.all([listFolders(), getMailboxes()]);
54	      folders = f;
55	      mailboxes = mb;
56	    }
57	
58	    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
59	    list = await listMessages(inboxPath, 1, undefined, active);
60	    // Signature for the active mailbox (best effort — never fail the page on it).
61	    signature = await getMailboxSettings(active)
62	      .then((s) => s.signature)
63	      .catch(() => "");
64	  } catch {
65	    failed = true;
66	  }
67	
68	  if (failed || folders.length === 0) {
69	    // WHY a diagnosis instead of one message: this page used to render a single
70	    // "No mailbox connected" for every cause, so "you have no email plan",
71	    // "your domain isn't verified yet", "your mailbox exists but we never
72	    // captured its password" and "the mail server is down" all read as the same
73	    // dead end. `mailAccessState` also runs Mailcow discovery, so a mailbox that
74	    // exists on the mail server without a local row is adopted BEFORE we tell
75	    // anyone they don't have one — the "it's not detecting the mailbox I already
76	    // have" report.
77	    const state = await mailAccessState(user.id).catch(
78	      () => ({ kind: "no-subscription" }) as MailAccessState,
79	    );
80	    return (
81	      <div className="mx-auto max-w-2xl pt-10">
82	        <MailUnavailable state={state} />
83	      </div>
84	    );
85	  }
86	
87	  // The shared dashboard <main> wraps every route in `max-w-7xl px-4 py-8
88	  // sm:px-6`. Mail is a full-app surface, so we cancel that padding with
89	  // negative margins to let the client run full-height (no blank space below)
90	  // and edge-to-edge up to the layout's max width. Going wider than max-w-7xl
91	  // on very large monitors would require editing the shared layout, which this
92	  // route intentionally leaves untouched.
93	  return (
94	    <div className="h-full">
95	      <MailClient
96	        initialFolders={folders}
97	        initialMailboxes={mailboxes}
98	        initialList={list}
99	        initialFolderPath={inboxPath}
100	        initialSignature={signature}
101	        initialActiveAddress={active}
102	      />
103	    </div>
104	  );
105	}
106	
107	/** One empty state per real cause, each with the action that actually fixes it. */
108	function MailUnavailable({ state }: { state: MailAccessState }) {
109	  const emailLink = (
110	    <Link href="/dashboard/email" className="btn-primary">
111	      Business Email
112	    </Link>
113	  );
114	
115	  switch (state.kind) {
116	    case "no-subscription":
117	      return (
118	        <EmptyState
119	          title="No email plan yet"
120	          sub="Webmail needs a mailbox on one of your domains. Add business email to a domain and your inbox appears here."
121	          action={
122	            <Link href="/dashboard/email" className="btn-primary">
123	              Set up email
124	            </Link>
125	          }
126	        />
127	      );
128	
129	    case "unverified-domain":
130	      return (
131	        <EmptyState
132	          title="Finish verifying your domain"
133	          sub={`${state.domains.join(", ")} still needs its DNS records published and verified. Mailboxes can't go live — and mail won't route — until that succeeds.`}
134	          action={emailLink}
135	        />
136	      );
137	
138	    case "no-mailbox":
139	      return (
140	        <EmptyState
141	          title="No mailbox created yet"
142	          sub={`${state.domains.join(", ")} is verified and ready. Create your first mailbox (like you@${state.domains[0] ?? "yourdomain.com"}) to start using webmail.`}
143	          action={emailLink}
144	        />
145	      );
146	
147	    case "no-password":
148	      return (
149	        <EmptyState
150	          title="Reset your mailbox password to continue"
151	          sub={`We can see ${state.address} on the mail server, but we don't hold a password for it — so we can't sign in to IMAP on your behalf. Reset the password on the Business Email page and webmail will open here.`}
152	          action={emailLink}
153	        />
154	      );
155	
156	    case "server-unreachable":
157	      return (
158	        <EmptyState
159	          title="Couldn't reach your mailbox"
160	          sub={`${state.address} is set up, but the mail server didn't answer just now. This is usually temporary — reload in a moment. If it keeps happening, open a ticket and we'll look at the server.`}
161	          action={
162	            <Link href="/dashboard/support" className="btn-secondary">
163	              Contact support
164	            </Link>
165	          }
166	        />
167	      );
168	
169	    default:
170	      return (
171	        <EmptyState
172	          title="No mailbox connected"
173	          sub="We couldn't reach a mailbox for your account."
174	          action={emailLink}
175	        />
176	      );
177	  }
178	}
