1	import { requireUser } from "@/lib/auth";
2	import { db } from "@/lib/db";
3	import { AutoRefresh } from "@/components/AutoRefresh";
4	import { SitesManager, type TemplateChoice } from "@/components/customer/site-builder/SitesManager";
5	import type { SiteRow } from "@/lib/actions-sites";
6	import { SITE_TEMPLATES } from "@/lib/site-templates";
7	
8	export const dynamic = "force-dynamic";
9	
10	const BASE_DOMAIN = process.env.SITE_BUILDER_BASE_DOMAIN || "nxeon.site";
11	
12	export default async function SitesPage() {
13	  const user = await requireUser();
14	
15	  const sites = await db.site.findMany({
16	    where: { userId: user.id },
17	    orderBy: { updatedAt: "desc" },
18	  });
19	
20	  const rows: SiteRow[] = sites.map((s) => ({
21	    id: s.id,
22	    name: s.name,
23	    slug: s.slug,
24	    status: s.status,
25	    templateKey: s.templateKey,
26	    publishedAt: s.publishedAt ? s.publishedAt.toISOString() : null,
27	    error: s.error,
28	    updatedAt: s.updatedAt.toISOString(),
29	  }));
30	
31	  const templates: TemplateChoice[] = SITE_TEMPLATES.map((t) => ({
32	    key: t.key,
33	    name: t.name,
34	    description: t.description,
35	    accent: t.accent,
36	  }));
37	
38	  // Refresh while any site is mid-publish so the status flips without a manual
39	  // reload (the worker is serial, so a publish can briefly queue).
40	  const anyBusy = rows.some((r) => r.status === "PUBLISHING");
41	
42	  return (
43	    <>
44	      {anyBusy && <AutoRefresh intervalMs={5000} />}
45	      <SitesManager sites={rows} templates={templates} baseDomain={BASE_DOMAIN} />
46	    </>
47	  );
48	}
