1	"use client";
2	
3	/**
4	 * Customer-facing site list + create/publish controls for the Website Builder.
5	 *
6	 * All mutations go through the `"use server"` actions in lib/actions-sites.ts,
7	 * which authenticate and ownership-check every call — this component only drives
8	 * the UI and surfaces the result.
9	 */
10	import { useState, useTransition } from "react";
11	import Link from "next/link";
12	import { useRouter } from "next/navigation";
13	import {
14	  createSite,
15	  publishSite,
16	  unpublishSite,
17	  deleteSite,
18	} from "@/lib/actions-sites";
19	import type { SiteRow } from "@/lib/actions-sites";
20	import { PageHeader, EmptyState, StatusDot, Badge } from "@/components/ui/primitives";
21	
22	export type TemplateChoice = {
23	  key: string;
24	  name: string;
25	  description: string;
26	  accent: string;
27	};
28	
29	export function SitesManager({
30	  sites,
31	  templates,
32	  baseDomain,
33	}: {
34	  sites: SiteRow[];
35	  templates: TemplateChoice[];
36	  baseDomain: string;
37	}) {
38	  const router = useRouter();
39	  const [name, setName] = useState("");
40	  const [templateKey, setTemplateKey] = useState(templates[0]?.key ?? "");
41	  const [error, setError] = useState<string | null>(null);
42	  const [pending, start] = useTransition();
43	
44	  function onCreate() {
45	    setError(null);
46	    start(async () => {
47	      const res = await createSite(name.trim() || "My site", templateKey);
48	      if (!res.ok) {
49	        setError(res.error);
50	        return;
51	      }
52	      router.push(`/dashboard/sites/${res.id}`);
53	    });
54	  }
55	
56	  function onPublish(id: string) {
57	    setError(null);
58	    start(async () => {
59	      const res = await publishSite(id);
60	      if (!res.ok) setError(res.error);
61	      router.refresh();
62	    });
63	  }
64	
65	  function onUnpublish(id: string) {
66	    setError(null);
67	    start(async () => {
68	      const res = await unpublishSite(id);
69	      if (!res.ok) setError(res.error);
70	      router.refresh();
71	    });
72	  }
73	
74	  function onDelete(id: string) {
75	    setError(null);
76	    if (!confirm("Delete this site permanently? This cannot be undone.")) return;
77	    start(async () => {
78	      const res = await deleteSite(id);
79	      if (!res.ok) setError(res.error);
80	      router.refresh();
81	    });
82	  }
83	
84	  return (
85	    <div>
86	      <PageHeader
87	        title="Website builder"
88	        sub="Pick a template, edit it in your browser, and publish a live site in one click."
89	      />
90	
91	      {error && (
92	        <div className="card mb-4 border-red-500/40 bg-red-500/10 p-3 text-sm text-red-300">{error}</div>
93	      )}
94	
95	      {/* Create a new site */}
96	      <div className="card mb-8 p-5">
97	        <h2 className="mb-4 text-sm font-semibold text-slate-200">Create a new site</h2>
98	        <div className="mb-4 grid gap-3 sm:grid-cols-3">
99	          {templates.map((t) => (
100	            <button
101	              key={t.key}
102	              type="button"
103	              onClick={() => setTemplateKey(t.key)}
104	              className={`rounded-xl border p-4 text-left transition ${
105	                templateKey === t.key
106	                  ? "border-brand-500 bg-brand-500/10"
107	                  : "border-white/10 bg-white/[0.03] hover:border-white/20"
108	              }`}
109	            >
110	              <div className="mb-2 h-2 w-10 rounded-full" style={{ background: t.accent }} />
111	              <div className="text-sm font-semibold">{t.name}</div>
112	              <div className="mt-1 text-xs text-slate-400">{t.description}</div>
113	            </button>
114	          ))}
115	        </div>
116	        <div className="flex flex-wrap items-center gap-3">
117	          <input
118	            value={name}
119	            onChange={(e) => setName(e.target.value)}
120	            placeholder="Site name (e.g. My Cafe)"
121	            maxLength={80}
122	            className="min-w-[220px] flex-1 rounded-lg border border-white/10 bg-navy-950/60 px-3 py-2 text-sm outline-none focus:border-brand-500"
123	          />
124	          <button
125	            type="button"
126	            onClick={onCreate}
127	            disabled={pending}
128	            className="rounded-lg bg-brand-500 px-5 py-2 text-sm font-semibold text-white disabled:opacity-50"
129	          >
130	            {pending ? "Working…" : "Create site"}
131	          </button>
132	        </div>
133	      </div>
134	
135	      {/* Existing sites */}
136	      {sites.length === 0 ? (
137	        <EmptyState
138	          title="No sites yet"
139	          sub="Choose a template above to start building your first website."
140	        />
141	      ) : (
142	        <div className="space-y-3">
143	          {sites.map((s) => {
144	            const domain = `${s.slug}.${baseDomain}`;
145	            const live = s.status === "PUBLISHED";
146	            const busy = s.status === "PUBLISHING";
147	            return (
148	              <div key={s.id} className="card flex flex-wrap items-center justify-between gap-4 p-4">
149	                <div className="min-w-0">
150	                  <div className="flex items-center gap-2">
151	                    <span className="truncate font-semibold">{s.name}</span>
152	                    <StatusDot status={s.status} />
153	                  </div>
154	                  <div className="mt-1 text-xs text-slate-400">
155	                    {live ? (
156	                      <a
157	                        href={`http://${domain}/`}
158	                        target="_blank"
159	                        rel="noreferrer"
160	                        className="text-brand-300 hover:underline"
161	                      >
162	                        {domain}
163	                      </a>
164	                    ) : (
165	                      <span>{domain}</span>
166	                    )}
167	                    {s.templateKey && (
168	                      <>
169	                        {" · "}
170	                        <Badge tone="slate">{s.templateKey}</Badge>
171	                      </>
172	                    )}
173	                  </div>
174	                  {s.status === "FAILED" && s.error && (
175	                    <div className="mt-1 max-w-xl text-xs text-red-300">{s.error}</div>
176	                  )}
177	                </div>
178	                <div className="flex flex-wrap items-center gap-2">
179	                  <Link
180	                    href={`/dashboard/sites/${s.id}`}
181	                    className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25"
182	                  >
183	                    Edit
184	                  </Link>
185	                  {live || s.status === "FAILED" ? (
186	                    <button
187	                      type="button"
188	                      onClick={() => onUnpublish(s.id)}
189	                      disabled={pending || busy}
190	                      className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25 disabled:opacity-50"
191	                    >
192	                      Take offline
193	                    </button>
194	                  ) : (
195	                    <button
196	                      type="button"
197	                      onClick={() => onPublish(s.id)}
198	                      disabled={pending || busy}
199	                      className="rounded-lg bg-brand-500 px-3 py-1.5 text-sm font-semibold text-white disabled:opacity-50"
200	                    >
201	                      {busy ? "Publishing…" : "Publish"}
202	                    </button>
203	                  )}
204	                  <button
205	                    type="button"
206	                    onClick={() => onDelete(s.id)}
207	                    disabled={pending || live || busy}
208	                    className="rounded-lg border border-white/10 px-3 py-1.5 text-sm text-red-300 hover:border-red-500/40 disabled:opacity-40"
209	                  >
210	                    Delete
211	                  </button>
212	                </div>
213	              </div>
214	            );
215	          })}
216	        </div>
217	      )}
218	    </div>
219	  );
220	}
