22	function ClaudeGlyph({ className = "" }: { className?: string }) {
23	  // Owner-provided Claude brand asset — the single source of truth for the mark.
24	  return <Image src="/logos/claude.png" alt="Claude" width={28} height={28} className={className} aria-hidden />;
25	}
