27	function CopyButton({ text, label = "Copy", className = "" }: { text: string; label?: string; className?: string }) {
28	  const [copied, setCopied] = useState(false);
29	  return (
30	    <button
31	      type="button"
32	      onClick={async () => {
33	        try {
34	          await navigator.clipboard.writeText(text);
35	          setCopied(true);
36	          setTimeout(() => setCopied(false), 1600);
37	        } catch {
38	          /* clipboard unavailable */
