136	        <mark key={idx++} className="rounded bg-brand-500/25 px-1 text-brand-100">
137	          {v || `{${m[1]}}`}
138	        </mark>
139	      );
140	      last = m.index + m[0].length;
141	    }
142	    if (last < tmpl.prompt.length) parts.push(tmpl.prompt.slice(last));
143	    return parts;
